(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.3)*20+Math.cos(y*0.012-t*0.2)*15+Math.sin((x+y)*0.008+t*0.5)*10;
  const w1y = Math.cos(y*0.015-t*0.25)*20+Math.sin(x*0.013+t*0.35)*15+Math.cos((x-y)*0.009-t*0.4)*10;
  const w2x = Math.sin(w1x*0.02+t*0.15)*8+Math.cos(w1y*0.025-t*0.2)*6;
  const w2y = Math.cos(w1y*0.02-t*0.18)*8+Math.sin(w1x*0.022+t*0.22)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src1 = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9]
  ];
  const src2 = [
    [80+Math.cos(t*0.45)*60,40+Math.sin(t*0.65)*40,0.15,-1.3],
    [400+Math.sin(t*0.55)*70,200+Math.cos(t*0.75)*50,0.13,-1.6],
    [200+Math.sin(t*0.7+3)*90,220+Math.cos(t*0.5+2)*60,0.11,-1.1],
    [350+Math.cos(t*0.4+1)*50,100+Math.sin(t*0.6+4)*70,0.17,-1.8],
    [60+Math.sin(t*0.85+2)*55,150+Math.cos(t*0.45+1)*45,0.14,-1.4]
  ];
  let aS=0,iS=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp]of src1){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const pulse=0.8+Math.sin(t*0.3+sp)*0.2;
    aS+=Math.sin(d*f-t*sp)*pulse;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*pulse;
  }
  for(const[sX,sY,f,sp]of src2){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const pulse=0.7+Math.cos(t*0.4-sp)*0.3;
    aS2+=Math.sin(d*f-t*sp)*pulse;
    iS2+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*pulse;
  }
  const act=aS/6,inh=iS/6,act2=aS2/5,inh2=iS2/5;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+sy*0.06-t*1.8)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.03+ang*2-t*0.8)*Math.cos(dist*0.07-ang*5+t*1.7)*0.3;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2=Math.sin(Math.floor(sx*0.08)*1.7+Math.floor(sy*0.08)*2.3+t*0.5)*0.12;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2=Math.tanh((act2-inh2*0.6+spiral*0.5+bg*0.4)*2.0);
  const coupling=Math.sin(rd1*rd2*3.14)*0.25;
  const feed=Math.sin(dist*0.02-t*0.5)*0.15;
  const reaction=Math.tanh((rd1+rd2*0.4+coupling+cell*0.2+cell2+feed)*1.7);
  const v=reaction*0.5+0.5;
  const hueShift=Math.sin(t*0.1)*0.02;
  const pal=[
    [4,8,42],[8,28,78],[10,58,112],[15,95,128],[30,140,132],
    [90,172,115],[160,195,80],[215,200,60],[235,160,55],
    [225,110,65],[190,65,72],[140,38,68],[85,20,58],[40,12,48],[4,8,42]
  ];
  const adj=(v+hueShift%1+1)%1;
  const idx=adj*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.78?1.14:(Math.abs(reaction)>0.5?1.06:1.0);
  const glow=Math.max(0,1-Math.abs(reaction))*0.12;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*45)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*35)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*55)|0
  ];
}
